section.literal_block:
class NotVeryGoodLock: def __init__(self): self._blocked_tasks = collections.deque() self._held = False
async def acquire(self): # We might have to try several times to acquire the lock. while self._held: # Someone else has the lock, so we have to wait. task = trio.lowlevel.current_task() self._blocked_tasks.append(task) def abort_fn(_): self._blocked_tasks.remove(task) return trio.lowlevel.Abort.SUCCEEDED await trio.lowlevel.wait_task_rescheduled(abort_fn) # At this point the lock was released -- but someone else # might have swooped in and taken it again before we # woke up. So we loop around to check the 'while' condition # again. # if we reach this point, it means that the 'while' condition # has just failed, so we know no-one is holding the lock, and # we can take it. self._held = True
def release(self): self._held = False if self._blocked_tasks: woken_task = self._blocked_tasks.popleft() trio.lowlevel.reschedule(woken_task)

list_item.paragraph:
Polling: this is where you use a busy-loop to manually check
                            for IO on both event loops many times per second. This adds latency,
                            and wastes CPU time and electricity.

